    },
    {
      "indicator": "MM50",
      "reading": "30.8990",
      "interpretation": "Suporte de médio prazo; MM50 ainda abaixo da MM200, o que limita confirmação de alta de longo prazo."
    },
    {
      "indicator": "MM200",
      "reading": "31.6201",
      "interpretation": "Suporte de longo prazo; preço acima da MM200 sugere viés altista estrutural, mas falta confirmação plena enquanto MM50 < MM200."
    },
    {
      "indicator": "EMA9",
      "reading": "32.3904",
      "interpretation": "EMA9 > EMA21 indica impulso de curtíssimo prazo; porém preço fechou abaixo da EMA9, sinalizando perda de força."
    },
    {
      "indicator": "EMA21",
      "reading": "32.0386",
      "interpretation": "EMA21 próximo ao MM20 e atuando como suporte dinâmico de curto/médio prazo."
    },
    {
      "indicator": "MACD (12,26,9)",
      "reading": "MACD 0.4817 / signal 0.5943 / hist -0.1126",
      "interpretation": "MACD positivo mas abaixo da linha de sinal; histograma negativo indica desaceleração do momentum e risco de correção/consolidação."
    },
    {
      "indicator": "Bandas de Bollinger (20,2σ)",
      "reading": "BB_lower 30.0728 / BB_mid 32.0465 / BB_upper 34.0202",
      "interpretation": "Preço próximo à banda média; bandas relativamente largas (volatilidade residual); sem squeeze — consolidando dentro das bandas."
    },
    {
      "indicator": "RSI14",
      "reading": "54.8706",
      "interpretation": "RSI em zona neutra (≈55): sem sobrecompra/oversold; leve viés comprador, mas sem excesso."
    },
    {
      "indicator": "Volume",
      "reading": "15095715300",
      "interpretation": "Volume do pregão reduzido (15.0957B), inferior aos picos de março (ex.: 31634433800 em 2025-03-31). Baixa convicção no movimento atual."
    }
  ]
